g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "complexity-table",
  "x": 80, "y": 160, "width": 1120, "height": 290,
  "header_rows": 1,
  "column_widths": [300, 280, 260, 280],
  "row_heights": [50, 60, 60, 60, 60],
  "style": {"font_family": "Segoe UI", "font_size": 18, "border_color": "#3C5A80", "border_width": 1, "band_row": false},
  "columns": [
    {"text": "Layer type", "fill": "#10284A", "color": "#9CC3E6", "bold": true, "align": "l", "font_size": 14},
    {"text": "Complexity per layer", "fill": "#10284A", "color": "#9CC3E6", "bold": true, "align": "ctr", "font_size": 14},
    {"text": "Sequential operations", "fill": "#10284A", "color": "#9CC3E6", "bold": true, "align": "ctr", "font_size": 14},
    {"text": "Maximum path length", "fill": "#10284A", "color": "#9CC3E6", "bold": true, "align": "ctr", "font_size": 14}
  ],
  "rows": [
    [
      {"text": "Self-Attention", "fill": "#15325A", "color": "#F5A623", "bold": true, "align": "l"},
      {"text": "O(n² · d)", "fill": "#15325A", "color": "#F5A623", "align": "ctr"},
      {"text": "O(1)", "fill": "#15325A", "color": "#F5A623", "align": "ctr"},
      {"text": "O(1)", "fill": "#15325A", "color": "#F5A623", "bold": true, "align": "ctr"}
    ],
    [
      {"text": "Recurrent", "color": "#E8F1FA", "align": "l"},
      {"text": "O(n · d²)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(n)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(n)", "color": "#E8F1FA", "align": "ctr"}
    ],
    [
      {"text": "Convolutional", "color": "#E8F1FA", "align": "l"},
      {"text": "O(k · n · d²)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(1)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(log_k n)", "color": "#E8F1FA", "align": "ctr"}
    ],
    [
      {"text": "Self-Attention (restricted)", "color": "#E8F1FA", "align": "l"},
      {"text": "O(r · n · d)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(1)", "color": "#E8F1FA", "align": "ctr"},
      {"text": "O(n / r)", "color": "#E8F1FA", "align": "ctr"}
    ]
  ]
}
